    tableCaption: "Renewal discovery worksheet", columns: ["Signal", "Question and next action"], rows: [["Usage decline", "Which users and workflows changed, and why?"],["Open support issues", "What impact remains and who owns resolution?"],["Sponsor change", "Who now owns the business goal and decision?"],["Missing success criteria", "What outcome would make renewal worthwhile to the customer?"]],
