    tableCaption: "Demo planning worksheet", columns: ["Demo segment", "Decision it supports"], rows: [["Problem confirmation", "Agree which request-routing issue matters."],["Synthetic request", "Show a relevant input without using customer data."],["Routing and ownership", "Explain why the chosen team receives the case."],["Integration question", "Clarify the external system and technical requirements."],["Recovery", "State the failure, use a labelled backup and record the follow-up."]],
