    tableCaption: "Metric reconciliation worksheet", columns: ["Definition", "Question to answer"], rows: [["Event", "Order created or payment settled?"],["Date boundary", "Which timezone and reporting period apply?"],["Record scope", "Which states, refunds and exclusions are included?"],["Join and grain", "One row per order, payment or another event?"],["Business question", "Bookings, cash receipt or campaign-related behaviour?"]],
