    tableCaption: "Prioritisation worksheet", columns: ["Request", "Evidence and constraint to examine"], rows: [["Onboarding change", "Where users struggle and whether the step blocks first value."],["Data export", "The prospective customer's need and any verified commitment."],["Dashboard refresh", "A specific usability issue rather than appearance alone."],["Capacity", "Dependency, implementation uncertainty and opportunity cost."],["Decision", "How the selected work supports the agreed objective."]],
